import (
    "fmt"
    "sync"
)

func main() {
    var wg sync.WaitGroup

    wg.Add(2)
    go func() {
        defer wg.Done()
        result, err := IntsToJSON([]int32{1, 2, 3})
        fmt.Printf("Slice 1: %s, err=%v\n", result, err)
    }()
    go func() {
        defer wg.Done()
        result, err := IntsToJSON([]int32{4, 5, 6, 7, 8})
        fmt.Printf("Slice 2: %s, err=%v\n", result, err)
    }()
    wg.Wait()
}
```

